export function Tenant({
  tenant = "{{tenant}}",
  accent = "{{accent}}",
  showScope = {{showScope}},
  appName = "{{appName}}",
}) {
  const names = { acme: "Acme Co", globex: "Globex", initech: "Initech" };
  const scopes = { acme: "1,204 records visible to Acme Co only", globex: "388 records visible to Globex only", initech: "92 records visible to Initech only" };
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", borderRadius: 12, width: 300, boxSizing: "border-box", overflow: "hidden", border: "1.5px solid #24143018" }}>
      <div style={{ display: "flex", alignItems: "center", padding: "12px 14px", background: accent }}>
        <span style={{ fontWeight: 800 }}>{names[tenant]}</span>
        <span style={{ marginLeft: "auto", fontSize: 11, opacity: .8 }}>{appName}</span>
      </div>
      {showScope && <p style={{ margin: 0, padding: "12px 14px", fontSize: 11, color: "#24143099" }}>Scope: {scopes[tenant]}</p>}
    </div>
  );
}
